  function openCompanyExecutiveDialog(){if(controlUser()?.role!=='Developer')return toast('Developer permission is required.');const users=companyExecutiveUsers(),select=$('companyExecutiveUser');$('companyExecutiveForm').reset();$('companyExecutiveCode').dataset.auto='true';$('companyExecutivePosition').value='Country Director (CD)';$('companyExecutiveSystemRole').value='Administrator';select.innerHTML='<option value="">Select name</option>'+users.map(u=>`<option value="${esc(u.id)}">${esc(u.name||u.id)} · ${esc(u.role||'Employee')}</option>`).join('');$('companyExecutiveSave').disabled=!users.length;if(!users.length)select.innerHTML='<option value="">No registered users available</option>';renderCompanyExecutivePreview();$('companyExecutiveDialog').showModal();}
