  /* Management insights and report launchers */
  function selectedMonthSessions(){const prefix=state.month.slice(0,7);return state.mtsSessions.filter(x=>String(x.work_date||'').startsWith(prefix));}
  function workDayTotals(rows){const totals={};for(const x of rows.filter(x=>x.status==='completed')){const d=new Date(`${x.work_date}T12:00:00`),name=d.toLocaleDateString('en-US',{weekday:'long'});totals[name]=(totals[name]||0)+Number(x.duration_hours||0);}return Object.entries(totals).sort((a,b)=>b[1]-a[1]);}
