    $('recruitVacancyAnalytics').innerHTML=vacancies.length?vacancies.map(v=>{const n=candidates.filter(c=>c.vacancyId===v.id).length;return `<article><span><b>${esc(v.title)}</b><small>${esc(v.department||'')}</small></span><strong>${n}</strong></article>`;}).join(''):'<div class="insight-empty">No live vacancies yet.</div>';
