    $('calendarForm').addEventListener('submit',async e=>{e.preventDefault();const payload=()=>({date:$('calendarDateInput').value,day_type:$('calendarTypeInput').value,standard_hours:Number($('calendarHoursInput').value||0),holiday_source:$('calendarSourceInput').value});await submit('calendarForm','/api/live/calendar',payload,()=>engine.upsertCalendar({date:$('calendarDateInput').value,dayType:$('calendarTypeInput').value,standardHours:Number($('calendarHoursInput').value||0),holidaySource:$('calendarSourceInput').value}),'Calendar day saved to live data.');$('calendarHoursInput').value='8';});
