  /* Master Time Schedule + Recovery Passport unified evidence spine */
  function populateMtsMasters(){
    if(!$('mtsEmployee'))return;
    if($('mtsEmployeeIds')) $('mtsEmployeeIds').innerHTML=engine.state.employees.map(e=>`<option value="${esc(e.employeeId)}">${esc(e.name)}${e.position?` · ${esc(e.position)}`:''}</option>`).join('');
    if($('mtsProjectCodes')) $('mtsProjectCodes').innerHTML=engine.state.projects.filter(p=>p.status==='Active').map(p=>`<option value="${esc(p.code)}">${esc(p.name||p.code)}${p.donor?` · ${esc(p.donor)}`:''}</option>`).join('');
    const sessionMonths=state.mtsSessions.map(x=>String(x.work_date||'').slice(0,7)).filter(Boolean);
    const monthValues=[...new Set([...engine.state.calendar.map(x=>x.month?.slice(0,7)),...sessionMonths].filter(Boolean))].sort();
    $('mtsMonthFilter').innerHTML='<option value="">All months</option>'+monthValues.map(m=>`<option value="${m}">${window.ADRAEngine.monthLabel(m+'-01')}</option>`).join('');
    const years=[...new Set([...engine.state.calendar.map(x=>String(x.date||'').slice(0,4)),...state.mtsSessions.map(x=>String(x.work_date||'').slice(0,4))].filter(Boolean))].sort();
    $('mtsYearFilter').innerHTML='<option value="">All years</option>'+years.map(y=>`<option>${y}</option>`).join('');
  }
  function progressBand(value){const v=Math.max(0,Math.min(100,Number(value||0)));if(v>=100)return {className:'progress-complete',labelClass:'complete',label:'Complete'};if(v>=80)return {className:'progress-near',labelClass:'near',label:'Near completion'};if(v>=50)return {className:'progress-moderate',labelClass:'moderate',label:'Moderate'};return {className:'progress-incomplete',labelClass:'incomplete',label:'Incomplete'};}
  function elapsedTaskDays(row){const start=new Date(row?.created_at||row?.clock_in_at||0),end=new Date(row?.status==='completed'?(row.clock_out_at||row.updated_at||Date.now()):Date.now());if(Number.isNaN(start.getTime())||Number.isNaN(end.getTime()))return 0;return Math.max(1,Math.ceil((end-start)/86400000));}
  function localMtsStore(){return previewMemory.mts;}
  function saveLocalMtsStore(v){previewMemory.mts={sessions:Array.isArray(v?.sessions)?v.sessions:[],messages:Array.isArray(v?.messages)?v.messages:[]};queueStandaloneSave();}
  function mtsUid(prefix='MTS'){return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2,7)}`;}
  function mtsDurationHours(a,b){const x=new Date(a).getTime(),y=new Date(b).getTime();return Number.isFinite(x)&&Number.isFinite(y)&&y>x?Math.round(((y-x)/3600000)*1000000)/1000000:0;}
  function legacyHoursClient(r){const h=mtsDurationHours(r.clockInTimestamp,r.clockOutTimestamp);if(h)return h;const str=String(r.totalHours||'').toLowerCase(),n=parseFloat(str);if(!Number.isFinite(n))return 0;if(str.includes('min'))return n/60;if(str.includes('sec'))return n/3600;return n;}
  function legacyIsoClient(date,time,timestamp){if(timestamp&&Number.isFinite(Number(timestamp)))return new Date(Number(timestamp)).toISOString();const d=date||new Date().toISOString().slice(0,10);if(!time)return new Date(`${d}T08:00:00`).toISOString();const p=new Date(`${d} ${time}`);return Number.isNaN(p.getTime())?new Date(`${d}T08:00:00`).toISOString():p.toISOString();}
  function normalizeLegacyClient(r,i=0){const date=r.date||new Date().toISOString().slice(0,10),cin=legacyIsoClient(date,r.clockIn,r.clockInTimestamp),cout=(r.locked||r.clockOutTimestamp||r.clockOut)?legacyIsoClient(date,r.clockOut,r.clockOutTimestamp):null,h=cout?(mtsDurationHours(cin,cout)||legacyHoursClient(r)):0,project=String(r.project||'').trim()||'UNMAPPED',mapped=engine.state.projects.some(p=>p.code===project);return {id:r.id?`LEGACY-${r.id}`:mtsUid(`LEGACY-${i+1}`),employee_id:r.employeeId||'E001',employee_name:r.name||engine.state.employees[0]?.name||'Employee',department:r.department||'Unspecified',project_code:project,activity_description:r.activityDescription||'Imported legacy activity',work_date:date,clock_in_at:cin,clock_out_at:cout,duration_hours:h,completion_percent:Number(r.completion||0),on_time:Boolean(r.onTime),delay_comments:r.delaysChallenges||'',clock_in_location:r.clockInLocation||'',clock_out_location:r.clockOutLocation||'',document_name:r.documentName||'',document_type:r.documentType||'',document_size:Number(r.documentSize||0),document_data:r.documentData||'',status:cout?'completed':'active',locked:Boolean(cout),recovery_entry_id:null,recovery_bridge_status:mapped?(cout?'eligible_for_draft':'pending_clock_out'):'unmapped_project',source:'legacy_mts_import',created_at:cin,updated_at:cout||new Date().toISOString()};}
  function hydrateLocalMtsDrafts(){if(!STANDALONE_MODE)return;for(const row of localMtsStore().sessions){if(row.recovery_entry_id&&row.status==='completed'&&!engine.state.timeEntries.some(x=>x.entryId===row.recovery_entry_id)&&engine.state.projects.some(p=>p.code===row.project_code)){try{engine.addTimeEntry({entryId:row.recovery_entry_id,date:row.work_date,projectCode:row.project_code,hours:Number(row.duration_hours),activity:row.activity_description,status:'Draft',employeeId:row.employee_id||'E001',aiSuggestedProject:row.project_code,employeeDecision:'Accepted'});}catch{}}}}

  function bindMts(){
    if(!$('mtsClockInForm'))return;
    $('mtsClockInForm').addEventListener('submit',async e=>{e.preventDefault();await startMtsSession();});
    $('mtsEmployee').addEventListener('input',()=>{const employee=engine.state.employees.find(e=>e.employeeId===$('mtsEmployee').value.trim());if(employee&&!$('mtsEmployeeName').value.trim())$('mtsEmployeeName').value=employee.name||'';});
    $('mtsConfirmClockOut').addEventListener('click',async e=>{e.preventDefault();await completeMtsSession();});
    $('mtsModeControl').addEventListener('click',e=>{const b=e.target.closest('[data-mts-mode]');if(!b)return;state.mtsMode=b.dataset.mtsMode;document.querySelectorAll('[data-mts-mode]').forEach(x=>x.classList.toggle('active',x===b));renderMtsTable();});
    ['mtsSearch','mtsMonthFilter','mtsYearFilter'].forEach(id=>$(id).addEventListener(id==='mtsSearch'?'input':'change',()=>{renderMtsTable();renderMtsAnalytics();}));
    $('mtsPrevDay').addEventListener('click',()=>{state.mtsAnalyticsDateIndex=Math.max(0,state.mtsAnalyticsDateIndex-1);renderMtsDaily();});
    $('mtsNextDay').addEventListener('click',()=>{const dates=currentMtsAnalytics().daily_analytics||[];state.mtsAnalyticsDateIndex=Math.min(Math.max(0,dates.length-1),state.mtsAnalyticsDateIndex+1);renderMtsDaily();});
    $('mtsJsonBtn').addEventListener('click',downloadMtsJson);$('mtsExcelBtn').addEventListener('click',exportMtsExcel);$('mtsImportBtn').addEventListener('click',()=>$('mtsImportInput').click());$('mtsImportInput').addEventListener('change',importMtsJson);
    $('mtsMessageForm').addEventListener('submit',async e=>{e.preventDefault();await sendMtsMessage();});
    $('mtsTable').addEventListener('click',async e=>{const c=e.target.closest('[data-mts-clockout]');if(c){openMtsClockOut(c.dataset.mtsClockout);return;}const t=e.target.closest('[data-mts-trace]');if(t){await showMtsTrace(t.dataset.mtsTrace);return;}const cm=e.target.closest('[data-mts-comment]');if(cm)alert(decodeURIComponent(cm.dataset.mtsComment)||'No comments.');});
  }
  async function documentPayload(){const f=$('mtsDocument').files?.[0];if(!f)return {};const out={name:f.name,type:f.type||'application/octet-stream',size:f.size,data:''};if(f.size>600000){toast('Document is larger than 600 KB; metadata will be stored but the file body will not be embedded in the local preview.');return out;}out.data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result||''));r.onerror=reject;r.readAsDataURL(f);});return out;}
  async function captureLocation(){if(!navigator.geolocation)return {label:'Location unavailable'};return new Promise(resolve=>{navigator.geolocation.getCurrentPosition(async p=>{const lat=p.coords.latitude,lng=p.coords.longitude;let label=`${lat.toFixed(5)}, ${lng.toFixed(5)}`;try{const r=await apiFetch(`https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${encodeURIComponent(lat)}&lon=${encodeURIComponent(lng)}`);if(r.ok){const d=await r.json();label=d.display_name||label;}}catch{}resolve({lat,lng,label});},()=>resolve({label:'Location not provided'}),{enableHighAccuracy:false,timeout:7000,maximumAge:60000});});}
  function ensureLocalMtsContext(employeeId,employeeName,department,projectCode,date){
    const existingEmployee=engine.state.employees.find(e=>e.employeeId===employeeId);
    if(!existingEmployee) engine.upsertEmployee({employeeId,name:employeeName,position:department,department,hoursPerDay:8,active:'Yes'});
    else {if(employeeName&&!existingEmployee.name)existingEmployee.name=employeeName;if(department&&!existingEmployee.department)existingEmployee.department=department;}
    let project=engine.state.projects.find(p=>p.code===projectCode);
    if(!project) project=engine.upsertProject({code:projectCode,name:projectCode,status:'Active',personnelBudget:0,eligibleEmployeeId:employeeId});
    else {const ids=String(project.eligibleEmployeeId||'').split(',').map(x=>x.trim()).filter(Boolean);if(!ids.includes(employeeId))project.eligibleEmployeeId=[...ids,employeeId].join(', ');}
    if(date&&!engine.state.calendar.some(c=>c.date===date)){const e=engine.state.employees.find(x=>x.employeeId===employeeId);engine.upsertCalendar({date,dayType:'Working Day',standardHours:Number(e?.hoursPerDay||8),holidaySource:'Auto-created from Work Activity Hub'});}const month=window.ADRAEngine.monthKey(date);if(month&&!engine.state.payroll.some(p=>p.month===month&&p.employeeId===employeeId))engine.upsertPayroll({month,employeeId,basicSalary:0,benefits:0,statutoryCost:0,exclusions:0,source:'Awaiting payroll input — created by Work Activity Hub',configurationStatus:'REVIEW',notes:'Live payroll placeholder only; enter authorized payroll amounts.'});
    persistLocalLiveState();
  }
  function syncLocalMtsSource(month){const sessions=localMtsStore().sessions.filter(x=>String(x.work_date||'').slice(0,7)===String(month).slice(0,7)),hours=sessions.filter(x=>x.status==='completed').reduce((a,x)=>a+Number(x.duration_hours||0),0);engine.upsertSourceCheck({month:String(month).slice(0,7)+'-01',check:'Work Activity Hub completed hours',sourceTarget:hours,severity:'Critical',whereToFix:'Work Activity Hub / Recovery Time Entry'});persistLocalLiveState();}
  async function startMtsSession(){
    const employeeId=$('mtsEmployee').value.trim(),employeeName=$('mtsEmployeeName').value.trim(),project=$('mtsProject').value.trim(),activity=$('mtsActivity').value.trim(),department=$('mtsDepartment').value;
    if(!employeeId)return toast('Enter an employee ID before clocking in.');if(!employeeName)return toast('Enter the employee name before clocking in.');if(!project)return toast('Enter a project code before clocking in.');if(!activity)return toast('Describe the activity before clocking in.');
    const active=state.mtsSessions.find(x=>['active','rework_required'].includes(x.status)&&x.employee_id===employeeId);if(active)return toast('This employee already has an active work session.');
    const button=$('mtsClockInForm').querySelector('button[type="submit"]');button.disabled=true;button.textContent='Capturing evidence…';
    try{const [geo,docPayload]=await Promise.all([captureLocation(),documentPayload()]);const clockInAt=new Date().toISOString(),payload={employee_id:employeeId,employee_name:employeeName,department,project_code:project,activity_description:activity,clock_in_at:clockInAt,location:geo,document:docPayload,session_id:sessionId()};let row;
      if(STANDALONE_MODE){ensureLocalMtsContext(employeeId,employeeName,department,project,clockInAt.slice(0,10));const store=localMtsStore();row={id:mtsUid(),employee_id:employeeId,employee_name:employeeName,department,project_code:project,activity_description:activity,work_date:clockInAt.slice(0,10),clock_in_at:clockInAt,clock_out_at:null,duration_hours:0,completion_percent:0,on_time:false,delay_comments:'',clock_in_location:geo.label||'',clock_out_location:'',clock_in_lat:geo.lat??null,clock_in_lng:geo.lng??null,clock_out_lat:null,clock_out_lng:null,document_name:docPayload.name||'',document_type:docPayload.type||'',document_size:docPayload.size||0,document_data:docPayload.data||'',status:'active',locked:false,recovery_entry_id:null,recovery_bridge_status:'pending_clock_out',source:'live',created_at:new Date().toISOString(),updated_at:new Date().toISOString()};store.sessions.push(row);saveLocalMtsStore(store);if(docPayload.name){const c=localControlStore();c.documents.unshift({id:`DOC-${crypto.randomUUID()}`,name:docPayload.name,type:docPayload.type,size:docPayload.size,data:docPayload.data,source:'Work Activity Hub',sourceRef:row.id,department,projectCode:project,employeeId,employeeName,uploadedBy:employeeName,uploadedAt:new Date().toISOString(),status:'PENDING_REVIEW',assignedTo:controlActorId(),analysisStatus:'AI_MODEL_NOT_CONFIGURED',analysisMode:'AUTOMATED_PRE_SCREEN',analysisSummary:'Work Activity supporting document captured and queued for human review.',archivePath:''});saveLocalControlStore(c);}}
      else{const res=await apiFetch('/api/mts/clock-in',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});const body=await res.json();if(!res.ok)throw new Error(body.error||'Could not clock in.');row=body;await loadLiveState();}
      $('mtsActivity').value='';$('mtsDocument').value='';populateMonths();populateMtsMasters();toast(`Clocked in to ${row.project_code}. Work Activity Hub is now feeding the connected live data model.`);await renderMts();await refreshControlCenter();
    }catch(err){toast(err.message||'Could not clock in.');}finally{button.disabled=false;button.textContent='● Clock In';}
  }
  function openMtsClockOut(id){const row=state.mtsSessions.find(x=>String(x.id)===String(id));if(!row)return;$('mtsClockOutId').value=row.id;$('mtsCompletion').value=row.status==='rework_required'?Math.max(80,Number(row.completion_percent||90)):100;$('mtsOnTime').value='true';$('mtsDelayComments').value='';$('mtsClockOutSummary').innerHTML=`<div><small>Employee</small>${userIdentity(row.employee_id,row.employee_name,row.employee_id,'xs')}</div><div><small>Project</small><b>${esc(row.project_code)}</b></div><div><small>Clocked in</small><b>${formatDateTime(row.clock_in_at)}</b></div><div><small>Activity</small><b>${esc(row.activity_description)}</b></div>${row.status==='rework_required'?'<div><small>Status</small><b>Document rework</b></div>':''}`;$('mtsClockOutDialog').showModal();}
  async function completeMtsSession(){
    const id=$('mtsClockOutId').value,row=state.mtsSessions.find(x=>String(x.id)===String(id));if(!row)return;const btn=$('mtsConfirmClockOut');btn.disabled=true;btn.textContent='Completing…';
    try{const loc=await captureLocation(),out=new Date().toISOString(),completion=Number($('mtsCompletion').value),onTime=$('mtsOnTime').value==='true',comments=$('mtsDelayComments').value.trim();let updated;
      if(STANDALONE_MODE){ensureLocalMtsContext(row.employee_id,row.employee_name,row.department,row.project_code,row.work_date);const store=localMtsStore(),idx=store.sessions.findIndex(x=>String(x.id)===String(id));if(idx<0)throw new Error('Work session not found.');updated={...store.sessions[idx],clock_out_at:out,duration_hours:mtsDurationHours(store.sessions[idx].clock_in_at,out),completion_percent:completion,on_time:onTime,delay_comments:comments,clock_out_location:loc.label||'',clock_out_lat:loc.lat??null,clock_out_lng:loc.lng??null,status:'completed',locked:true,updated_at:out};try{const draftId=`MTS-DRAFT-${updated.id}`;if(updated.duration_hours>0&&updated.duration_hours<=24){const draft=engine.addTimeEntry({entryId:draftId,date:updated.work_date,projectCode:updated.project_code,hours:updated.duration_hours,activity:updated.activity_description,status:'Draft',employeeId:updated.employee_id,aiSuggestedProject:updated.project_code,employeeDecision:'Accepted'});updated.recovery_entry_id=draft.entryId;updated.recovery_bridge_status='draft_created';}else updated.recovery_bridge_status='bridge_review';}catch(err){updated.recovery_bridge_status=`bridge_review: ${err.message}`;}store.sessions[idx]=updated;saveLocalMtsStore(store);syncLocalMtsSource(updated.work_date);persistLocalLiveState();}
      else{const res=await apiFetch(`/api/mts/sessions/${encodeURIComponent(id)}/clock-out`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({clock_out_at:out,location:loc,completion_percent:completion,on_time:onTime,delay_comments:comments,session_id:sessionId()})});const body=await res.json();if(!res.ok)throw new Error(body.error||'Could not clock out.');updated=body;await loadLiveState();}
      $('mtsClockOutDialog').close();populateMonths();populateMtsMasters();toast(updated.recovery_entry_id?`Clocked out. ${num(updated.duration_hours,2)} hours are now linked as draft recovery evidence and reflected across connected modules.`:`Clocked out. Recovery bridge requires review.`);await renderMts();refreshCurrent();
    }catch(err){toast(err.message||'Could not clock out.');}finally{btn.disabled=false;btn.textContent='Clock Out & create draft evidence';}
  }
  async function loadMtsData(){try{const [sessions,messages]=await Promise.all([apiFetch('/api/mts/sessions?limit=5000').then(r=>r.json()),apiFetch('/api/mts/messages?limit=100').then(r=>r.json())]);state.mtsSessions=Array.isArray(sessions)?sessions:[];state.mtsMessages=Array.isArray(messages)?messages:[];}catch(err){toast(`Work Activity data unavailable: ${err.message}`);state.mtsSessions=[];state.mtsMessages=[];}}
  function filteredMtsSessions(){const q=$('mtsSearch')?.value.trim().toLowerCase()||'',month=$('mtsMonthFilter')?.value||'',year=$('mtsYearFilter')?.value||'';return state.mtsSessions.filter(x=>(!month||String(x.work_date).startsWith(month))&&(!year||String(x.work_date).startsWith(year))&&(!q||[x.employee_name,x.department,x.project_code,x.activity_description,x.delay_comments,x.clock_in_location,x.clock_out_location].join(' ').toLowerCase().includes(q)));}
  function mtsAnalytics(rows){const completed=(rows||[]).filter(x=>x.status==='completed'&&Number(x.duration_hours)>0),sum=(a,f)=>a.reduce((s,x)=>s+Number(f(x)||0),0),perf=(key)=>{const g={};for(const x of completed){const name=String(x[key]||'Unspecified');g[name]??={hours:0,completion:0,n:0};g[name].hours+=Number(x.duration_hours||0);g[name].completion+=Number(x.completion_percent||0);g[name].n++;}const max=Math.max(0,...Object.values(g).map(x=>x.hours));return Object.entries(g).map(([name,d])=>({name,totalHours:d.hours,averageCompletion:d.n?d.completion/d.n:0,entries:d.n,weightedScore:(d.n?d.completion/d.n:0)*.7+(max?d.hours/max*100:0)*.3})).sort((a,b)=>b.weightedScore-a.weightedScore);};const employee=perf('employee_name'),dept=perf('department'),project=perf('project_code'),daily={};for(const x of completed){daily[x.work_date]??={date:x.work_date,earliest:null,latest:null,totalHours:0};const d=daily[x.work_date];d.totalHours+=Number(x.duration_hours||0);if(!d.earliest||new Date(x.clock_in_at)<new Date(d.earliest.clock_in_at))d.earliest=x;if(!d.latest||new Date(x.clock_out_at)>new Date(d.latest.clock_out_at))d.latest=x;}const oed={};for(const x of completed){const k=`${x.work_date}__${x.employee_name}`;oed[k]=(oed[k]||0)+Number(x.duration_hours||0);}const overtime=Object.entries(oed).filter(([,h])=>h>8).map(([k,h])=>{const [date,employee_name]=k.split('__');return {date,employee_name,hours:h};});const jobs={};for(const x of completed){jobs[x.project_code]??={project_code:x.project_code,completed:0,total:0,totalHours:0};jobs[x.project_code].total++;jobs[x.project_code].totalHours+=Number(x.duration_hours||0);if(Number(x.completion_percent)===100)jobs[x.project_code].completed++;}const byMonth={};for(const x of completed){const m=String(x.work_date).slice(0,7);byMonth[m]=(byMonth[m]||0)+Number(x.duration_hours||0);}return {total_sessions:rows.length,active_sessions:rows.filter(x=>['active','rework_required'].includes(x.status)).length,completed_sessions:completed.length,total_hours:sum(completed,x=>x.duration_hours),average_completion:completed.length?sum(completed,x=>x.completion_percent)/completed.length:0,recovery_drafts:completed.filter(x=>x.recovery_entry_id).length,top_workers:employee.slice(0,3),employee_performance:employee,department_performance:dept,project_performance:project,daily_analytics:Object.values(daily).sort((a,b)=>a.date.localeCompare(b.date)),employee_of_month:employee[0]||null,jobs_analytics:Object.values(jobs).sort((a,b)=>b.totalHours-a.totalHours),overtime,hours_by_month:Object.entries(byMonth).sort().map(([month,hours])=>({month,hours}))};}
  function currentMtsAnalytics(){return mtsAnalytics(filteredMtsSessions());}
  async function renderMts(){if(!$('mtsKpis'))return;await loadMtsData();populateMtsMasters();renderMtsActive();renderMtsTable();renderMtsAnalytics();renderMtsMessages();}
