  async function sendMtsMessage(){const recipient=$('mtsMessageRecipient').value.trim(),content=$('mtsMessageContent').value.trim();if(!recipient||!content)return;try{let row;if(STANDALONE_MODE){const store=localMtsStore();row={id:mtsUid('MSG'),recipient,sender:'Recovery Passport System',content,read:false,created_at:new Date().toISOString()};store.messages.unshift(row);saveLocalMtsStore(store);}else{const res=await apiFetch('/api/mts/messages',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({recipient,content,session_id:sessionId()})});const body=await res.json();if(!res.ok)throw new Error(body.error||'Could not send message.');row=body;}$('mtsMessageForm').reset();toast('Internal message stored in the system inbox.');await renderMts();}catch(err){toast(err.message);}}
  async function showMtsTrace(id){try{let trace;if(STANDALONE_MODE){const s=state.mtsSessions.find(x=>String(x.id)===String(id)),entry=s?.recovery_entry_id?engine.analyzedTimeEntries().find(x=>x.entryId===s.recovery_entry_id):null,monthly=entry?engine.monthlyEngine().find(x=>x.month===entry.month):null,passport=entry?engine.recoveryPassport(entry.month,entry.projectCode):null;trace={mts_session:s,recovery_time_entry:entry,monthly_engine:monthly,recovery_passport:passport};}else{const res=await apiFetch(`/api/mts/evidence/${encodeURIComponent(id)}`);trace=await res.json();if(!res.ok)throw new Error(trace.error||'Trace unavailable.');}const s=trace.mts_session,e=trace.recovery_time_entry,m=trace.monthly_engine,p=trace.recovery_passport;alert(`UNIFIED WORK-EVIDENCE TRACE\n\nMTS Session: ${s?.id||'—'}\nActivity: ${s?.activity_description||'—'}\nElapsed hours: ${num(s?.duration_hours||0,2)}\nRecovery entry: ${e?.entryId||s?.recovery_entry_id||'Not bridged'}\nEntry status: ${e?.status||'—'}\nDaily check: ${e?.dailyCheck||'—'}\nEligibility: ${e?.projectEligibility||'—'}\nMonthly posting: ${m?.postingStatus||'—'}\nRecovery Gate: ${p?.recoveryGate??'—'}\nFinal Recovery status: ${p?.finalStatus||'—'}\n\nThe MTS record is evidence; final accounting authorization still depends on the Recovery Passport controls.`);}catch(err){toast(err.message);}}
