  function addMessage(role,text,temporary=false,label=''){const empty=$('agentEmptyState');if(empty)empty.remove();const d=document.createElement('div');d.className=`message ${role}${label?' proactive':''}`;d.innerHTML=`${label?`<small class="message-label">${esc(label)}</small>`:''}<div class="bubble">${esc(text).replace(/\n/g,'<br>')}</div>`;$('chatMessages').appendChild(d);$('chatMessages').scrollTop=$('chatMessages').scrollHeight;return d;}

  function readLocalMappings(){return previewMemory.mappings;}
  function localLearnedSuggestion(activity){
    const words=s=>new Set(String(s||'').toLowerCase().match(/[a-z0-9]+/g)||[]), target=words(activity);let best=null;
    for(const row of readLocalMappings()){
      const w=words(row.activity||row.activity_key), inter=[...target].filter(x=>w.has(x)).length, union=new Set([...target,...w]).size||1, score=inter/union;
      if(!best||score>best.score)best={...row,score};
    }
    return best&&best.score>0?best:null;
  }


