  function deriveLocalControl(c){
    const reviewer=c.profile?.currentUser,assigned=reviewer?.canReview||reviewer?.role==='Administrator',reviews=[];
    if(assigned){for(const r of engine.state.timeEntries){if(r.status==='Draft')reviews.push({id:`TIME:${r.entryId}:SUPERVISOR`,kind:'TIME_EVIDENCE',title:'Supervisor time-evidence approval',detail:`${r.employee||r.employeeId} · ${r.projectCode} · ${r.hours} hrs`,status:'PENDING',actionMode:'approve_reject',sourceRef:r.entryId,stage:'SUPERVISOR'});else if(r.status==='Supervisor approved')reviews.push({id:`TIME:${r.entryId}:FINANCE`,kind:'TIME_EVIDENCE',title:'Finance time-evidence approval',detail:`${r.employee||r.employeeId} · ${r.projectCode} · ${r.hours} hrs`,status:'PENDING',actionMode:'approve_reject',sourceRef:r.entryId,stage:'FINANCE'});}for(const r of engine.state.payroll.filter(x=>String(x.configurationStatus).toUpperCase()==='REVIEW'))reviews.push({id:`PAYROLL:${r.month}:${r.employeeId}`,kind:'PAYROLL_CONFIGURATION',title:'Payroll configuration review',detail:`${r.employeeId} · ${r.month}`,status:'PENDING',actionMode:'approve_reject',sourceRef:`${r.month}__${r.employeeId}`});for(const d of (c.documents||[]).filter(x=>x.status==='PENDING_REVIEW'))reviews.push({id:`DOCUMENT:${d.id}`,kind:'DOCUMENT',title:'Document approval',detail:d.name,status:'PENDING',actionMode:'approve_reject',sourceRef:d.id});for(const m of engine.monthlyEngine().filter(x=>x.postingStatus!=='READY TO POST')){const item={id:`BLOCK:${m.month}:${m.postingStatus}:${m.criticalExceptions}`,kind:'CONTROL_BLOCK',title:'Blocked recovery period',detail:`${m.monthLabel} · ${m.criticalExceptions} critical exception(s)`,status:'BLOCKED',actionMode:'acknowledge',sourceRef:m.month};if(!c.reviewResolutions?.[item.id])reviews.push(item);}}
    c.reviews=reviews;const store=localMtsStore(),ids=new Set([reviewer?.id,reviewer?.name,reviewer?.email].filter(Boolean).map(x=>String(x).toLowerCase()));c.messages=(store.messages||[]).filter(x=>!x.read&&(!x.recipient||ids.has(String(x.recipient).toLowerCase())||['all','everyone','system'].includes(String(x.recipient).toLowerCase())));c.notifications=[...reviews.map(r=>({id:`review:${r.id}`,kind:'review',title:r.title,detail:r.detail,review_id:r.id,status:r.status})),...c.messages.map(m=>({id:`message:${m.id}`,kind:'message',title:`Message from ${m.sender||'System'}`,detail:m.content,message_id:m.id,status:'UNREAD'}))];return c;
  }
