  async function runControlReview(id,action){
    const review=(state.control?.reviews||[]).find(x=>x.id===id);if(!review)return;try{
      if(review.kind==='AGENT_ACTION'&&review.approvalState){const approved=action==='approve',r=await apiFetch('/api/brain/resume',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({approval_state:review.approvalState,decisions:(review.approvals||[]).map(()=>approved),actor_id:controlActorId()})}),b=await r.json();if(!r.ok)throw new Error(b.error||'Could not resume Recovery Agent.');await apiFetch(`/api/control-center/reviews/${encodeURIComponent(id)}/resolve`,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({decision:action,actorId:controlActorId()})});addMessage('assistant',b.output_text||'Agent review completed.');if($('approvalDialog')?.open)$('approvalDialog').close();if(b.requires_approval){const again={...b,text:b.output_text};await registerAgentReview(again);pendingApproval=again;}else pendingApproval=null;
      }else if(STANDALONE_MODE){if(review.kind==='TIME_EVIDENCE'){const row=engine.state.timeEntries.find(x=>x.entryId===review.sourceRef);if(row)row.status=action==='approve'?(review.stage==='SUPERVISOR'?'Supervisor approved':'Finance approved'):'Rejected';persistLocalLiveState();}else if(review.kind==='DOCUMENT'){const c=localControlStore(),d=c.documents.find(x=>x.id===review.sourceRef);if(d){d.status=action==='approve'?'APPROVED':'REJECTED';if(action==='approve')d.archivePath=`${d.department||'Unassigned Department'} / ${d.projectCode||'Unassigned Project'} / ${d.employeeId||d.employeeName||'Unassigned Employee'}`;saveLocalControlStore(c);}}else if(review.kind==='CONTROL_BLOCK'){const c=localControlStore();c.reviewResolutions=c.reviewResolutions||{};c.reviewResolutions[review.id]={action,at:new Date().toISOString(),by:controlActorId()};saveLocalControlStore(c);toast('Blocker acknowledged. Resolve its source control before posting.');}}
      else{const r=await apiFetch(`/api/control-center/reviews/${encodeURIComponent(id)}/action`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action,actorId:controlActorId()})}),b=await r.json();if(!r.ok)throw new Error(b.error||'Review action failed.');}
      toast(action==='approve'?'Approved.':action==='reject'?'Rejected.':'Review acknowledged.');await loadLiveState();await refreshControlCenter();populateMonths();refreshCurrent();
    }catch(err){toast(err.message);}
  }

